    "mcp-skills/package.json": "{\n  \"name\": \"__PACKAGE_NAME__\",\n  \"version\": \"0.1.0\",\n  \"type\": \"module\",\n  \"license\": \"Apache-2.0\",\n  \"engines\": {\n    \"node\": \">=24.10\"\n  },\n  \"exports\": \"./dist/index.js\",\n  \"files\": [\n    \"dist\",\n    \"client\",\n    \"skills\",\n    \"mcp.json\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json\",\n    \"test\": \"node --import tsx --test\"\n  },\n  \"dependencies\": {\n    \"@agnes/plugin-runtime\": \"0.0.0\",\n    \"@agnes/extension-api\": \"^4.0.0\",\n    \"@agnes/resource-control-runtime\": \"0.0.0\",\n    \"@agnes/protocol\": \"0.0.0\"\n  },\n  \"devDependencies\": {\n    \"typescript\": \"7.0.2\",\n    \"@types/node\": \"26.4.1\",\n    \"tsx\": \"4.23.13\",\n    \"@agnes/host\": \"0.0.0\"\n  },\n  \"agnes\": {\n    \"plugins\": [\n      {\n        \"export\": \"main\",\n        \"apiRange\": \"^4.0.0\",\n        \"id\": \"ext:__PACKAGE_NAME__/main\",\n        \"inject\": [\n          \"skills\"\n        ],\n        \"capabilities\": {}\n      }\n    ],\n    \"hostProvidedExternals\": {\n      \"@agnes/plugin-runtime\": \"0.0.0\",\n      \"@agnes/extension-api\": \"^4.0.0\",\n      \"@agnes/resource-control-runtime\": \"0.0.0\",\n      \"@agnes/protocol\": \"0.0.0\"\n    },\n    \"provides\": [\n      \"skills\"\n    ]\n  }\n}\n",
    "mcp-skills/skills/__SKILL_NAME__/SKILL.md": "---\nname: __SKILL_NAME__\ndescription: Use the bundled MCP integration to answer with evidence.\n---\n\nInspect the MCP tool catalog before calling a tool. Read the user's request, select the relevant read operation, and cite the returned evidence. Ask for missing inputs. Report connection failures clearly.\n",
    "mcp-skills/src/index.ts": "import { readFileSync } from 'node:fs'\nimport { type Context, defineAgnesPlugin } from '@agnes/plugin-runtime'\nimport type { McpServerDefinitionInput } from '@agnes/protocol'\nimport '@agnes/resource-control-runtime'\n\nexport const mcpServer: McpServerDefinitionInput = {\n  serverId: '__SKILL_NAME__',\n  displayName: '__PACKAGE_NAME__',\n  transport: { kind: 'http', url: 'http://127.0.0.1:3001/mcp' },\n  secretBinding: { kind: 'none' },\n}\nexport const main = defineAgnesPlugin({\n  apply(ctx: Context) {\n    const body = readFileSync(new URL('../skills/__SKILL_NAME__/SKILL.md', import.meta.url), 'utf8')\n    ctx.skills.register({\n      name: '__SKILL_NAME__',\n      description: 'Use the bundled MCP integration to answer with evidence.',\n      body,\n    })\n  },\n})\n",
    "mcp-skills/test/bundle.test.mjs": "import assert from 'node:assert/strict'\nimport { readFile } from 'node:fs/promises'\nimport { test } from 'node:test'\nimport { createPluginTestHost } from '@agnes/host/author-testkit'\nimport { main, mcpServer } from '../dist/index.js'\n\ntest('bundles matching config and registers the packaged skill', async () => {\n  const config = JSON.parse(await readFile(new URL('../mcp.json', import.meta.url), 'utf8'))\n  assert.deepEqual(mcpServer, config)\n  let skill\n  const host = await createPluginTestHost(main, {\n    services: {\n      skills: {\n        register(value) {\n          skill = value\n          return () => {}\n        },\n      },\n    },\n  })\n  try {\n    assert.equal(skill.name, '__SKILL_NAME__')\n    assert.match(skill.body, /Inspect the MCP tool catalog/)\n  } finally {\n    await host.dispose()\n  }\n})\n",
